CREATE TABLE "instrutor_qualificacao" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "instrutor_qualificacao_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"instrutor_id" integer NOT NULL,
	"descricao" varchar(200) NOT NULL,
	"treinamento_id" integer,
	"norma" varchar(120),
	"instituicao" varchar(160) NOT NULL,
	"data_emissao" date NOT NULL,
	"valida_ate" date,
	"comprovante_anexo_id" integer,
	"ativo" boolean DEFAULT true NOT NULL,
	"criado_por" integer NOT NULL,
	"criado_em" timestamp with time zone NOT NULL,
	"inativado_por" integer,
	"inativado_em" timestamp with time zone,
	CONSTRAINT "pk_instrutor_qualificacao" PRIMARY KEY("id"),
	CONSTRAINT "ck_qualificacao_fim" CHECK (treinamento_id IS NOT NULL OR norma IS NOT NULL),
	CONSTRAINT "ck_qualificacao_validade" CHECK (valida_ate IS NULL OR valida_ate >= data_emissao),
	CONSTRAINT "ck_qualificacao_inativacao" CHECK (ativo OR inativado_em IS NOT NULL)
);
